//! Liberation Sans advance tables, decoded from `metrics.bin`
//! (generated by `tools/font-metrics/DumpMetrics.java` from PlantUML's embedded tables).

use std::sync::OnceLock;

static BIN: &[u8] = include_bytes!("metrics.bin");

/// Index of the last record (of `stride` u16s, first is the start) whose start is <= `cp`.
fn last_start_le(ranges: &[u16], stride: usize, cp: u32) -> Option<usize> {
    let (mut lo, mut hi) = (0usize, ranges.len() / stride);
    while lo < hi {
        let mid = (lo + hi) / 2;
        if u32::from(ranges[mid * stride]) <= cp {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo.checked_sub(1)
}

/// Metrics of one face, in font units.
pub(super) struct FaceMetrics {
    pub units_per_em: u16,
    pub ascent: u16,
    pub descent: u16,
    pub line_gap: u16,
    pub missing_advance: u16,
    ranges: Vec<u16>,
    advances: Vec<u16>,
    offsets: Vec<usize>,
}

impl FaceMetrics {
    /// Advance width of a code point, or `None` if the face has no glyph for it.
    pub fn advance(&self, cp: u32) -> Option<u16> {
        if cp > 0xFFFF {
            return None;
        }
        let i = last_start_le(&self.ranges, 2, cp)?;
        let (first, last) = (
            u32::from(self.ranges[2 * i]),
            u32::from(self.ranges[2 * i + 1]),
        );
        if cp > last {
            return None;
        }
        Some(self.advances[self.offsets[i] + (cp - first) as usize])
    }
}

/// Widths measured with Java on Windows for logical fonts, in 2048ths of the size.
pub(super) struct MeasuredWidths {
    ranges: Vec<u16>,
    widths: Vec<u16>,
}

impl MeasuredWidths {
    /// `style`: 0 regular, 1 bold, 2 italic, 3 bold italic. `None` means the face width applies.
    pub fn width(&self, cp: u32, style: usize) -> Option<u16> {
        if cp > 0xFFFF {
            return None;
        }
        let i = last_start_le(&self.ranges, 3, cp)?;
        if cp > u32::from(self.ranges[3 * i + 1]) {
            return None;
        }
        let w = self.widths[4 * usize::from(self.ranges[3 * i + 2]) + style];
        (w != 0xFFFF).then_some(w)
    }
}

pub(super) struct Tables {
    /// Regular, bold, italic, bold italic.
    pub faces: [FaceMetrics; 4],
    pub measured: MeasuredWidths,
    /// Width table for 256-char blocks, in tenths of a pixel at size 16.
    pub blocks: Vec<Vec<u8>>,
}

struct Reader {
    pos: usize,
}

impl Reader {
    fn section(&mut self) -> Vec<u16> {
        let b = BIN;
        let n = u32::from_le_bytes([
            b[self.pos],
            b[self.pos + 1],
            b[self.pos + 2],
            b[self.pos + 3],
        ]) as usize;
        self.pos += 4;
        let v = (0..n)
            .map(|i| u16::from_le_bytes([b[self.pos + 2 * i], b[self.pos + 2 * i + 1]]))
            .collect();
        self.pos += 2 * n;
        v
    }
}

fn face(r: &mut Reader) -> FaceMetrics {
    let h = r.section();
    let ranges = r.section();
    let advances = r.section();
    let mut offsets = Vec::with_capacity(ranges.len() / 2);
    let mut off = 0usize;
    for c in ranges.chunks_exact(2) {
        offsets.push(off);
        off += usize::from(c[1]) - usize::from(c[0]) + 1;
    }
    debug_assert_eq!(off, advances.len());
    FaceMetrics {
        units_per_em: h[0],
        ascent: h[1],
        descent: h[2],
        line_gap: h[3],
        missing_advance: h[4],
        ranges,
        advances,
        offsets,
    }
}

fn decode_block(data: Vec<u16>) -> Vec<u8> {
    if data.len() != 1 && data.len() < 256 {
        let mut out = Vec::with_capacity(256);
        for p in data.chunks_exact(2) {
            out.extend(std::iter::repeat_n(p[1] as u8, usize::from(p[0])));
        }
        out
    } else {
        data.into_iter().map(|v| v as u8).collect()
    }
}

pub(super) fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let mut r = Reader { pos: 0 };
        let faces = [face(&mut r), face(&mut r), face(&mut r), face(&mut r)];
        let ranges = r.section();
        let widths = r.section();
        let count = r.section()[0] as usize;
        let blocks = (0..count).map(|_| decode_block(r.section())).collect();
        Tables {
            faces,
            measured: MeasuredWidths { ranges, widths },
            blocks,
        }
    })
}

/// Width of a code point in the generic table, at reference size 16 (`UnicodeBlock.getWidth`).
pub(super) fn table_width(cp: u32) -> f64 {
    if cp >= 0xFFFF {
        return 16.0;
    }
    let t = tables();
    let block = (cp >> 8) as usize;
    match t.blocks.get(block) {
        None => 13.0,
        Some(d) if d.len() == 1 => f64::from(d[0]) / 10.0,
        Some(d) => f64::from(d[(cp & 0xFF) as usize]) / 10.0,
    }
}
